def find(o, path=''):
    if isinstance(o, dict):
        for k,v in o.items():
            if 'onedrive' in str(k).lower() or 'onedrive' in str(v).lower():
                print(path+'/'+str(k), '->', v if not isinstance(v,(dict,list)) else type(v))
            find(v, path+'/'+str(k))
    elif isinstance(o, list):
        for i,v in enumerate(o):
            find(v, path+f'[{i}]')
